def main() -> None:
    data = json.loads(STORIES.read_text(encoding="utf-8"))
    existing = {s["id"] for s in data}
    added = []
    for sid, item in CLASSICS.items():
        if len(item) == 2:
            title, text = item
            series = "国外经典"
            cat, age, icon = ["名著", "冒险"], "8岁+", "📚"
        else:
            title, series, cat, age, icon, text = item
        if sid in existing:
            print(f"!! 已存在 {sid}")
            continue
        data.append({
            "id": sid,
            "type": "story",
            "title": title,
            "cover": "",
            "icon": icon,
            "category": cat,
            "age": age,
            "duration": "10分钟",
            "text": text,
            "audio": f"assets/audio/{sid}.mp3",
            "source": f"{series}（Project Gutenberg 英文公版改写）",
            "license": "公共领域",
            "series": series,
        })
        added.append(sid)
    STORIES.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"已新增 {len(added)} 条: {added}")

    if "--audio" in sys.argv:
        voice = "zh-CN-XiaoyiNeural"  # 活泼儿童向女声（晓伊+35Hz音调+10%语速）
        for sid in added:
            s = next(x for x in data if x["id"] == sid)
            out = AUDIO_DIR / f"{sid}.mp3"
            subprocess.run(
                ["edge-tts", "--voice", voice, "--pitch=+35Hz", "--rate=+10%", "--text", s["text"], "--write-media", str(out)],
                check=True, capture_output=True,
            )
            print(f"音频已生成: {out.name} ({len(s['text'])}字)")


if __name__ == "__main__":
    main()
